            $("#attatchment_table").on("click", "a.confirm-delete", function(event) {
                event.preventDefault();
                var id = $(this).attr('value');
                $.ajax({
                    url: '{{ route('admin.policy.attachment-confirm-delete') }}',
                    data: {
                        "_token": "{{ csrf_token() }}",
                        "id": id
                    },
                    type: 'post',
                    datatype: 'json',
                    success: function(data) {
                        var append =
                            '<div class="modal-header"><h5 class="modal-title" id="exampleModalLabel">Delete </h5>' +
                            '<button type="button" class="close" data-dismiss="modal" aria-label="Close"> <span aria-hidden="true">&times;</span> </button> ' +
                            '</div> ' +
                            '<div class="modal-body"> ' +
                            '<p>' + data.body + '</p> ' +
                            '</div> ' +
                            '<div class="modal-footer"> ' +
                            '<button type="button" class="btn btn-outline-brand" data-dismiss="modal">Close</button> ';
                        $('#modal-content-attachment').html(append);
                        if (data.status == 'success') {
                            var url = '{{ route('admin.policy.attachment_delete', ':id') }}';
                            url = url.replace(':id', data.id);

                            append += '<a href="' + url +
                                '" type="button" class="btn btn-brand">Delete</a></div>';
