                    responsive: true,
                    pageLength: 12,
                    order: [[1, 'desc']], // Sort by period descending
                    language: {
                        processing: "<img src='{{ asset('img/loading.gif') }}'>"
                    },
                    dom: 'Bfrtip',
                    buttons: [
                        'copy', 'csv', 'excel', 'pdf', 'print'
                    ],
                    footerCallback: function(row, data, start, end, display) {
                        var api = this.api();

                        // Calculate totals for visible rows
                        var distanceTotal = api.column(3, {page: 'current'}).data().reduce(function(a, b) {
                            return parseFloat(a) + parseFloat(b.replace(/,/g, ''));
                        }, 0);

                        var premiumTotal = api.column(5, {page: 'current'}).data().reduce(function(a, b) {
                            return parseFloat(a) + parseFloat(b.replace(/P|,/g, ''));
                        }, 0);

                        // Update footer
                        $(api.column(3).footer()).html('<strong>' + distanceTotal.toFixed(2) + ' km</strong>');
                        $(api.column(5).footer()).html('<strong>P' + premiumTotal.toFixed(2) + '</strong>');
                    }
                });
            };
            initObdPremiumTable();
