            jQuery(document).ready(function() {


                var deviceType = '';

                $(document).on('change', '.device_type', function() {
                    var selectMake = $(this).parent().parent().next().children().eq(0).find('select');
                    var deviceType = $(this).val();
                    ajaxRequest = setTimeout(function(sn) {
                        $.ajax({
                            url: "https://graphite.alphadirect.co.bw/api/frontendpay/deviceBrands",
                            data: {
                                "_token": "{{ csrf_token() }}",
                                "deviceType": deviceType
                            },
                            type: 'post',
                            datatype: 'json',
                            beforeSend: function() {
                                $("#loader").show();
                            },
                            success: function(data) {
                                var brandName = data.Brands;
                                selectMake.empty();
                                $.each(brandName, function(key, val) {
                                    selectMake.append('<option value="' + val.id +
                                        '">' + val.name + '</option>');
                                });
                                selectMake.append($(
                                    '<option value="Other">Other</option>'));
                            },
                            error: function() {
                                //$("#cell_phone_make").append($('<option value="">NO '+deviceType+' BRAND FOUND</option>'));
                            },
                            complete: function(data) {
                                $("#loader").hide();
                            },
                        });
                    }, 200);
                });

                $(document).on('change', '.cell_phone_make', function() {
                    var selectModel = $(this).parent().parent().next().children().eq(0).find('select');
                    var brand = $(this).val();
                    var deviceType = $(this).val();
                    $('#cell_phone_model').empty();
                    if ($(this).val() === 'Other') {
                        $(this).parent().parent().next(".make_other").show();
                        $(this).parent().parent().next().children().eq(1).rules('add', {
                            required: true,
                            messages: {
                                required: "Please enter Make"
                            }
                        });
                    } else {
                        $(this).parent().parent().next(".make_other").hide();
                        $(this).parent().parent().next().children().eq(1).rules('remove', 'required');
                        ajaxRequest = setTimeout(function(sn) {
                            $.ajax({
                                url: "https://graphite.alphadirect.co.bw/api/frontendpay/deviceBrandModels",
                                data: {
                                    "_token": "{{ csrf_token() }}",
                                    "brand": brand
                                },
                                type: 'post',
                                datatype: 'json',
                                beforeSend: function() {
                                    $("#loader").show();
                                },
                                success: function(data) {
                                    var ModelName = data.Models;
                                    selectModel.empty();
                                    $.each(ModelName, function(key, val) {
                                        selectModel.append($('<option value="' + val
                                            .id + '">' + val.name +
                                            '</option>'));
                                    });
                                    selectModel.append($(
                                        '<option value="Other">Other</option>'));
                                },
                                error: function() {
                                    //selectModel.append($('<option value="">NO '+brand+' MODEL FOUND</option>'));
                                },
                                complete: function(data) {
                                    $("#loader").hide();
                                },
                            });
                        }, 200);
                    }
                });

                $(document).on('change', '.cell_phone_model', function() {
                    if ($(this).val() === 'Other') {

                        $(this).parent().next(".model_other").show();
                        $(this).parent().next().children().eq(1).rules('add', {
                            required: true,
                            messages: {
                                required: "Please enter Model"
                            }
                        });
                    } else {
                        $(this).parent().next(".model_other").hide();
                        $(this).parent().next().children().eq(1).rules('remove', 'required');
                    }
