                        orientation: "bottom left",
                        // templates: arrows,
                        format: 'dd-mm-yyyy',
                        startDate: "-65y",
                        endDate: "-18y",
                    });
                    $('.datepicker_age_limit_legal').datepicker({
                        rtl: KTUtil.isRTL(),
                        todayHighlight: true,
                        orientation: "bottom left",
                        // templates: arrows,
                        format: 'dd-mm-yyyy',
                        //startDate: "-65y",
                        endDate: "-18y",
                    });

                    // Hospital Cashback datepicker - block dates for age 65 and above
                    // Set startDate to 65 years ago to allow only dates that result in age under 65
                    var todayHcb = new Date();
                    todayHcb.setHours(0, 0, 0, 0);
                    
                    // Calculate startDate as exactly 65 years ago
                    var startDateHcb = new Date();
                    startDateHcb.setFullYear(startDateHcb.getFullYear() - 65);
                    startDateHcb.setHours(0, 0, 0, 0);
                    
                    $('.datepicker_age_limit_hcb').datepicker({
                        rtl: KTUtil.isRTL(),
                        todayHighlight: true,
                        orientation: "bottom left",
                        format: 'dd-mm-yyyy',
                        startDate: startDateHcb, // Only allow dates from 65 years ago onwards (age under 65)
                        endDate: "today",
                        beforeShowDay: function(date) {
                            // Additional check for precise age calculation
                            var selectedDate = new Date(date);
                            selectedDate.setHours(0, 0, 0, 0);
                            
                            // Calculate age accurately
                            var age = todayHcb.getFullYear() - selectedDate.getFullYear();
                            var monthDiff = todayHcb.getMonth() - selectedDate.getMonth();
                            var dayDiff = todayHcb.getDate() - selectedDate.getDate();
                            
                            // Adjust age if birthday hasn't occurred this year
                            if (monthDiff < 0 || (monthDiff === 0 && dayDiff < 0)) {
                                age--;
                            }
                            
                            // Disable dates that result in age 65 or above (but keep them visible)
                            if (age >= 65) {
                                return {enabled: false};
                            }
                            
                            return {enabled: true};
                        }
                    });

