            function removeBeneficiary(beneficiaryId) {
                var element = document.getElementById('beneficiary_' + beneficiaryId);
                if (element) {
                    element.remove();
                    updateBeneficiaryCount();
                }
            }

            function updateBeneficiaryCount() {
                // Count existing beneficiaries (those with "Existing" badge)
                var existingCount = document.querySelectorAll('.badge-primary').length;
                // Count new beneficiaries in the container
                var newCount = document.querySelectorAll('#newBeneficiariesContainer .kt-portlet').length;
                var totalCount = existingCount + newCount;

                // Update the count display if it exists
                var countElement = document.querySelector('.kt-portlet__body h5');
                if (countElement) {
                    if (totalCount > 0) {
                        countElement.innerHTML = '<i class="fa fa-users"></i> ' + totalCount + ' Beneficiar' + (totalCount > 1 ? 'ies' : 'y');
                    } else {
                        countElement.innerHTML = '<i class="fa fa-users"></i> No Beneficiaries';
                    }
                }
            }


