                        if (data) {
                            $.each(data.branches, function(index, value) {
                                var option = $('<option value="' + this.branch_id + '" selected>' +
                                    this.name + '</option>');
                                $("#bankBranchDropDown").append(option);
                            });
                        }
                    },
                    complete: function() {
                        $("#branchNameSpinner").css("display", "none");
                    },
                    error: function(data) {
                        alert('Failed to get branches');
                    }
                });

            });
