        <script>
            var has_member_val = $('#has_member_value').val();
            //console.log(has_member_val);
            if(has_member_val == 1) {
                $(document).ready(function() {
                    $(".beneficiaryPayment").each(function() {
                        $(this).rules('add',{
                           // required: true,
                            digits:true,
                            max : 100,
                            min : 1,
                            totalPercent:{
                                totalPercent: true
                            }
                        });
                    });

                    $("#addBeneficiary").click(function() {

                        jQuery.validator.addMethod("totalPercent", function (value, element) {
                                var total = 0;
                                $(".beneficiaryPayment").each(function(){
                                    if(parseInt($(this).val()) > 0){
                                        total += parseInt($(this).val());
                                    }
                                });
                                return total == 100;
                            }, function(params, element) {
                                return 'Total of beneficiary payout should equal 100%.'
                        });

                        jQuery.validator.addMethod("future", function(value, element) {
                            return this.optional(element) || Date.parse(value) < new Date().getTime(); //use Date.now() if you can instead of getTime, it's nicer
                        }, "Please enter only past dates");

                        $('.beneficiaryRelation').rules('add', {
                            required: true,
                            messages: {
                                required: "Please enter relationship"
                            }
                        });
                        $('.beneficiaryFName').rules('add', {
                            required: true,
                            messages: {
                                required: "Please enter first name"
                            }
                        });
                        $('.beneficiaryMName').rules('add', {
                            required: true,
                            messages: {
                                required: "Please enter middle name"
                            }
                        });
                        $('.beneficiaryLName').rules('add', {
                            required: true,
                            messages: {
                                required: "Please enter last name"
                            }
                        });
                        $('.beneficiaryDOB').rules('add', {
                            required: true,
                            future: true
                        });
                        $('.beneficiaryGender').rules('add', {
                            required: true,
                            messages: {
                                required: "Please select gender"
                            }
                        });
                        $(".beneficiaryPayment").each(function() {
                            $(this).rules('add',{
                                required: true,
                                digits:true,
                                max : 100,
                                min : 1,
                                totalPercent:{
                                    totalPercent: true
                                }
                            });
                        });
