    <script>
    $(document).ready(function() {
        $('#bundled_reload').modal('hide');
        $('#p1_m_a_d_i').on('change',function(){
           var baseURL = '<?php echo env('API_URL') ?>';
           var product_id = '<?php echo $policy->product_id ?>';
           var isChecked2 = document.getElementById("switchValue2").checked;
           var  t_p_c_ivalue = document.getElementById('t_p_c_i').value;
           var  m_c_premium = document.getElementById('premium').value;
           if(isChecked2){
            add_t_p_c_i = 1;
           }else{
            add_t_p_c_i = 0;
           }
           var isChecked = document.getElementById("switchValue1").checked;
           var  p1_m_a_d_ivalue = document.getElementById('p1_m_a_d_i').value;
           if(isChecked){
            add_p1_m_a_d_i = 1;

           }else{
            add_p1_m_a_d_i = 0;

           }
            var isChecked3 = document.getElementById("switchValue3").checked;
            var motor_comprehensivevalue = document.getElementById('motor_comprehensive').value;
           if(isChecked3){
            add_motor_comprehensive = 1;
           }else{
            add_motor_comprehensive = 0;
           }

           var isChecked4 = document.getElementById("switchValue4").checked;
           var  legal_insurancevalue = document.getElementById('legal_insurance').value;
           if(isChecked4){
            add_legal_insurance = 1;
           }else{
            add_legal_insurance = 0;
           }

           var isChecked5 = document.getElementById("switchValue5").checked;
           var  c_d_insurancevalue = document.getElementById('c_d_insurance').value;
           if(isChecked5){
            add_c_d_insurance = 1;
           }else{
            add_c_d_insurance = 0;
           }
           var moter_comp_pre = document.getElementById("moter_comp_pre").value;
           if(moter_comp_pre != null){
            moter_comp_prem = document.getElementById("moter_comp_pre").value;
          }else{
            moter_comp_prem = 0;
           }

            ajaxRequest = setTimeout(function(sn) {
                $.ajax({
                url: baseURL+'frontendpay/life_insurance',
                data:  {
                    "_token"       : "{{ csrf_token() }}",
                    "add_t_p_c_i"       : add_t_p_c_i,
                    "t_p_c_i"       : t_p_c_ivalue,

                    "add_p1_m_a_d_i"       : add_p1_m_a_d_i,
                    "p1_m_a_d_i"       : p1_m_a_d_ivalue,

                    "add_motor_comprehensive"       : add_motor_comprehensive,
                    "motor_comprehensive"       : motor_comprehensivevalue,
                    "add_legal_insurance"       : add_legal_insurance,
                    "legal_insurance"       : legal_insurancevalue,
                    "add_c_d_insurance"       : add_c_d_insurance,
                    "c_d_insurance"       : c_d_insurancevalue,
                    "m_c_premium"       : m_c_premium,
                    "product_id"          : product_id,
                    "moter_comp_pre"          : moter_comp_prem,


                 },
                type: 'post',
                datatype : 'json',
                beforeSend: function(){
                    $("#loader").show();
                },
                success: function (data) {

                    $('#model_label').text('P '+data.p1_m_a_d_i_premium);

                    $('#subtotal').text('P '+data.subtotal);
                    $('#subtotal1').text('P '+data.subtotal);
                    $('#add_life_insurance').text('P '+data.add_life_insurance);
                    $('#discountrate').text(data.discount_rate+'%');
                    $('#discount').text('P '+data.discount);
                    $('#totalPremium').text('P '+data.totalPremium);
                    $('#t_p_c_i_premium').text('P '+data.t_p_c_i_premium);
                    $('#legal_insurance_premium').text('P '+data.legal_insurance_premium);
                    $('#c_d_insurance_premium').text('P '+data.c_d_insurance_premium);
                    $('#motor_comprehensive_premium').text('P '+data.motor_comprehensive_premium);
                    $('#product_id_3_premium').val(data.motor_comprehensive_premium);
                    $('#product_id_1_premium').val(data.p1_m_a_d_i_premium);
                    $('#product_id_2_premium').val(data.t_p_c_i_premium);
                    $('#product_id_6_premium').val(data.legal_insurance_premium);
                    $('#product_id_5_premium').val(data.c_d_insurance_premium);
                    $('#subtotal5').val(data.subtotal);
                    $('#bundled_discount_precent').val(data.discount_rate);
                    $('#bundled_discount').val(data.discount);
                    $('#final_premium').val(data.totalPremium);
                    $('#annualPremium').text(data.totalPremium);
                    $('#f_premium_i').text(data.totalPremium);
                    $('#f_premium_ii').text(data.totalPremium);
                    $('#f_premium_iii').text(data.totalPremium);
                    $('#f_premium_iv').text(data.totalPremium);
                     $('#discount_on').text(data.discount_on);



               },
               error: function (data) {
                    toastr.error(data.message);
                },
                complete: function (data) {
                    $("#loader").hide();
                },
            });
       }, 200);

   });
});

