  <script>

            $('body').on('focus',".kt_beneficiaryDOB", function(){
              var birth = $(this).val();

            if(birth != "")
            {
                var dateParts = birth.split("-");

                var dateObject = new Date(+dateParts[0], dateParts[1] - 1,+dateParts[2] );
                var currDate = new Date();
                var datecheck =  currDate.getFullYear() - 18;
                var datefield =  dateObject.getFullYear() ;
                if(datecheck >= datefield){
                    $(this).parents().next(".under_18_is").hide();
                    $(".kt_beneficiaryDOBchecked").prop('checked',false);

                }else{
                    $(".under_18_is").hide();
                    $(".kt_beneficiaryDOBchecked").prop('checked',false);
                    $(this).parents().next(".under_18_is").show();

                }




            }else{
                console.log("7");
            }
            });


</script>
