                url:'{!! route("admin.cancelPaymentArrangement",$policy->policyNumber) !!}'+ contractId,

                method: 'POST',
                data: {
                    _token: '{{ csrf_token() }}',
                    contractId:contractId
                },
                beforeSend: function(){
                        $("#loader").show();
                    },
                success: function(response) {
                    alert('Contract cancelled successfully.');
                    $('#paym_contract_list_table').DataTable().ajax.reload();
                    $("#loader").hide();
                },
                error: function(xhr) {
                    alert('Failed to cancel the contract.');
                    $("#loader").hide();
                }
            });
        }
    });

    $(document).on('click', '#paymCancelSchedule', function() {
        let scheduleId = $(this).data('id');
        if (confirm('Are you sure you want to cancel this schedule transaction?')) {
            $.ajax({
                url:'{!! route("admin.cancelScheduleTransaction",$policy->policyNumber) !!}',
                method: 'POST',
                data: {
                    _token: '{{ csrf_token() }}',
                    scheduleId: scheduleId
                },
                beforeSend: function(){
                    $("#loader").show();
                },
                success: function(response) {
                    alert('Schedule transaction cancelled successfully.');
                    $('#paym_sch_tr_contract_list_table').DataTable().ajax.reload();
                    $("#loader").hide();
                },
                error: function(xhr) {
                    alert('Failed to cancel the schedule transaction.');
                    $("#loader").hide();
                }
            });
        }
    });

    // Premium Calculations JavaScript
    $(document).ready(function() {
        let calculationsData = [];
        let policyNumberForCalc = '{{ $policy->policyNumber ?? '' }}';

        // Load previous calculations when tab is accessed
        function loadPreviousCalculations() {
            if (!policyNumberForCalc) return;

            $.ajax({
                url: '/admin/premium-calculator/policy-calculations',
                type: 'POST',
                data: {
                    policy_number: policyNumberForCalc,
                    _token: $('input[name="_token"]').val()
                },
                success: function(response) {
                    if (response.success && response.data.length > 0) {
                        calculationsData = response.data;
                        updateCalculationsTable();
                    }
                },
                error: function(xhr) {
                    console.error('Error loading previous calculations:', xhr);
                }
            });
        }

        // Load calculations when Premium Calculations tab is first accessed
        let calculationsLoaded = false;
        $('#premium-calculations-tab').one("click", function() {
            if (!calculationsLoaded) {
                loadPreviousCalculations();
                calculationsLoaded = true;
            }
        });

        // Fetch Premium Button Click
        $('#fetchPremiumBtn').on('click', function() {
            var policyNumber = $('#policy_number_input').val();
            var year = $('#calculation_year').val();
            var month = $('#calculation_month').val();

            if (!policyNumber) {
                alert('Error: Policy number not found!');
                return;
            }

            if (!year) {
                alert('Error: Please select a year!');
                return;
            }

            if (!month) {
                alert('Error: Please select a month!');
                return;
            }

            // Show spinner
            $('#calculationSpinner').removeClass('d-none');
            $('#fetchPremiumBtn').prop('disabled', true);

            // Prepare data
            var requestData = {
                policy_number: policyNumber,
                year: parseInt(year),
                month: parseInt(month),
                _token: $('input[name="_token"]').val()
            };

            // Make AJAX request
            $.ajax({
                url: '/admin/premium-calculator/calculate-from-policy',
                type: 'POST',
                data: requestData,
                success: function(response) {
                    console.log('Response received:', response);

                    if (response.success) {
                        // Hide modal
                        $('#premiumCalculationModal').modal('hide');

                        // Store calculation data
                        calculationsData.unshift(response.data);
                        console.log('Calculations data array:', calculationsData);

                        // Show success message
                        toastr.success('Premium calculated successfully!');

                        // Update table
                        updateCalculationsTable();

                        // Reset form
                        $('#premiumCalculationForm')[0].reset();
                    } else {
                        alert('Error: ' + (response.message || 'Failed to calculate premium'));
                    }
                },
                error: function(xhr) {
                    var errorMessage = 'An error occurred while calculating premium.';

                    if (xhr.responseJSON && xhr.responseJSON.message) {
                        errorMessage = xhr.responseJSON.message;
                    } else if (xhr.status === 404) {
                        errorMessage = 'Policy or trip data not found.';
                    } else if (xhr.status === 409) {
                        // Duplicate entry error
                        errorMessage = xhr.responseJSON.message || 'A calculation already exists for this policy and month.';
                    } else if (xhr.status === 422) {
                        var errors = xhr.responseJSON.errors;
                        errorMessage = Object.values(errors).flat().join('\\n');
                    }

                    alert('Calculation Failed: ' + errorMessage);
                },
                complete: function() {
                    // Hide spinner
                    $('#calculationSpinner').addClass('d-none');
                    $('#fetchPremiumBtn').prop('disabled', false);
                }
            });
        });

        // Update Calculations Table
        function updateCalculationsTable() {
            console.log('updateCalculationsTable called, data count:', calculationsData.length);

            var tbody = $('#calculationResults');
            tbody.empty();

            if (calculationsData.length === 0) {
                tbody.append(`
                    <tr>
                        <td colspan="12" class="text-center text-muted" style="padding: 50px;">
                            <div class="py-10">
                                <i class="flaticon-calculator" style="font-size: 48px; color: #ccc;"></i>
                                <p class="mt-4">No calculations yet. Click "Fetch Premium" to start.</p>
                            </div>
                        </td>
                    </tr>
                `);
                return;
            }

            calculationsData.forEach(function(calc, index) {
                var categoryBadge = getCategoryBadge(calc.behaviour_category);
                var sourceBadge = calc.premium_source === 'Policy Table'
                    ? '<span class="kt-badge kt-badge--success kt-badge--inline">Policy Table</span>'
                    : '<span class="kt-badge kt-badge--info kt-badge--inline">Rate API</span>';

                var distanceDisplay = calc.distance_adjustment
                    ? `<span class="text-warning" title="${calc.distance_adjustment}">${calc.billable_distance_km} km *</span>`
                    : `${calc.billable_distance_km} km`;

                // Format date - use created_at if available, otherwise use current date
                var displayDate = calc.created_at || new Date().toLocaleString();

                tbody.append(`
                    <tr>
                        <td>${displayDate}</td>
                        <td><strong>${calc.policy_number}</strong></td>
                        <td>${calc.vehicle_plate}</td>
                        <td>${calc.date_range.start} to ${calc.date_range.end}</td>
                        <td>${calc.date_range.days} days</td>
                        <td>${distanceDisplay}</td>
                        <td>${categoryBadge}</td>
                        <td><span class="font-weight-bold">${calc.average_optidrive.toFixed(4)}</span></td>
                        <td>${calc.trips_count}</td>
                        <td><strong class="text-primary">P ${calc.total_premium.toFixed(2)}</strong></td>
                        <td>${sourceBadge}</td>
                        <td>
                            <button class="btn btn-sm btn-primary" onclick="viewCalculationDetails(${index})">
                                <i class="flaticon-eye"></i> Details
                            </button>
                        </td>
                    </tr>
                `);
            });
        }

        // Get Category Badge
        function getCategoryBadge(category) {
            var badges = {
                'A': '<span class="kt-badge kt-badge--success kt-badge--inline">Category A</span>',
                'B': '<span class="kt-badge kt-badge--info kt-badge--inline">Category B</span>',
                'C': '<span class="kt-badge kt-badge--warning kt-badge--inline">Category C</span>',
                'D': '<span class="kt-badge kt-badge--danger kt-badge--inline">Category D</span>'
            };
            return badges[category] || category;
        }

        // View Calculation Details (Global function)
        window.viewCalculationDetails = function(index) {
            var calc = calculationsData[index];

            var detailsHTML = `
                <div class="row">
                    <!-- Policy Information -->
                    <div class="col-md-6">
                        <div class="kt-portlet kt-portlet--height-fluid">
                            <div class="kt-portlet__head">
                                <div class="kt-portlet__head-label">
                                    <h3 class="kt-portlet__head-title"><i class="flaticon-file"></i> Policy Information</h3>
                                </div>
                            </div>
                            <div class="kt-portlet__body">
                                <table class="table table-sm">
                                    <tr><td class="font-weight-bold">Policy Number:</td><td>${calc.policy_number}</td></tr>
                                    <tr><td class="font-weight-bold">Product ID:</td><td>${calc.policy_product_id}</td></tr>
                                    <tr><td class="font-weight-bold">Vehicle Plate:</td><td>${calc.vehicle_plate}</td></tr>
                                    <tr><td class="font-weight-bold">Premium Source:</td><td><span class="kt-badge kt-badge-${calc.premium_source === 'Policy Table' ? 'success' : 'info'} kt-badge--inline">${calc.premium_source}</span></td></tr>
                                </table>
                            </div>
                        </div>
                    </div>

                    <!-- Trip Information -->
                    <div class="col-md-6">
                        <div class="kt-portlet kt-portlet--height-fluid">
                            <div class="kt-portlet__head">
                                <div class="kt-portlet__head-label">
                                    <h3 class="kt-portlet__head-title"><i class="flaticon-car"></i> Trip Information</h3>
                                </div>
                            </div>
                            <div class="kt-portlet__body">
                                <table class="table table-sm">
                                    <tr><td class="font-weight-bold">Date Range:</td><td>${calc.date_range.start} to ${calc.date_range.end}</td></tr>
                                    <tr><td class="font-weight-bold">Duration:</td><td>${calc.date_range.days} days</td></tr>
                                    <tr><td class="font-weight-bold">Total Trips:</td><td>${calc.trips_count}</td></tr>
                                    <tr><td class="font-weight-bold">Actual Distance:</td><td>${calc.actual_distance_km} km</td></tr>
                                    <tr><td class="font-weight-bold">Billable Distance:</td><td>${calc.billable_distance_km} km ${calc.distance_adjustment ? '<span class="text-warning" title="' + calc.distance_adjustment + '"><i class="flaticon-information"></i></span>' : ''}</td></tr>
                                    ${calc.distance_range_min !== null && calc.distance_range_max !== null ? `
                                    <tr><td class="font-weight-bold">Distance Range:</td><td>${calc.distance_range_min} - ${calc.distance_range_max} km</td></tr>
                                    ` : ''}
                                    ${calc.distance_adjustment ? `<tr><td class="font-weight-bold text-warning">Adjustment:</td><td class="text-warning"><small>${calc.distance_adjustment}</small></td></tr>` : ''}
                                </table>
                            </div>
                        </div>
                    </div>

                    <!-- PPK Configuration Settings -->
                    <div class="col-md-12">
                        <div class="kt-portlet">
                            <div class="kt-portlet__head">
                                <div class="kt-portlet__head-label">
                                    <h3 class="kt-portlet__head-title"><i class="flaticon-settings"></i> PPK Configuration Settings Applied</h3>
                                </div>
                            </div>
                            <div class="kt-portlet__body">
                                <div class="row">
                                    <div class="col-md-6">
                                        <table class="table table-sm table-bordered">
                                            <thead>
                                                <tr>
                                                    <th>Setting</th>
                                                    <th>Status</th>
                                                    <th>Value</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                <tr>
                                                    <td class="font-weight-bold">Distance Range Configuration</td>
                                                    <td>
                                                        ${calc.distance_range_min !== null && calc.distance_range_max !== null 
                                                            ? '<span class="kt-badge kt-badge--success kt-badge--inline">Enabled</span>' 
                                                            : '<span class="kt-badge kt-badge--secondary kt-badge--inline">Disabled</span>'}
                                                    </td>
                                                    <td>
                                                        ${calc.distance_range_min !== null && calc.distance_range_max !== null 
                                                            ? `${calc.distance_range_min} - ${calc.distance_range_max} km` 
                                                            : 'Not Applied'}
                                                    </td>
                                                </tr>
                                                <tr>
                                                    <td class="font-weight-bold">OptiDrive Score Modifiers</td>
                                                    <td>
                                                        ${calc.behaviour_surcharge_percentage !== undefined 
                                                            ? '<span class="kt-badge kt-badge--success kt-badge--inline">Enabled</span>' 
                                                            : '<span class="kt-badge kt-badge--secondary kt-badge--inline">Disabled</span>'}
                                                    </td>
                                                    <td>
                                                        ${calc.behaviour_surcharge_percentage !== undefined 
                                                            ? `Category ${calc.behaviour_category}: ${calc.behaviour_surcharge_percentage}%` 
                                                            : 'Not Applied'}
                                                    </td>
                                                </tr>
                                            </tbody>
                                        </table>
                                    </div>
                                    <div class="col-md-6">
                                        <div class="alert alert-info">
                                            <h5><i class="flaticon-information"></i> Configuration Notes:</h5>
                                            <ul class="mb-0">
                                                ${calc.distance_range_min !== null && calc.distance_range_max !== null 
                                                    ? '<li><strong>Distance Range:</strong> Applied. Actual distance adjusted to billable distance based on min/max limits.</li>' 
                                                    : '<li><strong>Distance Range:</strong> Not applied. Using actual distance without adjustment.</li>'}
                                                ${calc.behaviour_surcharge_percentage !== undefined 
                                                    ? '<li><strong>OptiDrive Modifiers:</strong> Applied. Surcharge calculated from PPK config based on driver behavior category.</li>' 
                                                    : '<li><strong>OptiDrive Modifiers:</strong> Not applied. Using default surcharge values.</li>'}
                                            </ul>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>

                    <!-- Behaviour Analysis -->
                    <div class="col-md-12">
                        <div class="kt-portlet">
                            <div class="kt-portlet__head">
                                <div class="kt-portlet__head-label">
                                    <h3 class="kt-portlet__head-title"><i class="flaticon-dashboard"></i> Behaviour Analysis</h3>
                                </div>
                            </div>
                            <div class="kt-portlet__body">
                                <div class="row">
                                    <div class="col-md-3 text-center">
                                        <h2 class="text-primary">${calc.behaviour_category}</h2>
                                        <p>Category</p>
                                        ${getCategoryBadge(calc.behaviour_category)}
                                    </div>
                                    <div class="col-md-3 text-center">
                                        <h2 class="text-primary">${calc.average_optidrive.toFixed(4)}</h2>
                                        <p>Avg OptiDrive</p>
                                        <small class="text-muted">Auto-calculated from trips</small>
                                    </div>
                                    <div class="col-md-3 text-center">
                                        <h2 class="text-primary">${calc.behaviour_surcharge_percentage}%</h2>
                                        <p>Surcharge</p>
                                        <small class="text-muted">${calc.behaviour_category_auto_calculated ? 'Auto-calculated' : 'Manual'}</small>
                                    </div>
                                    <div class="col-md-3 text-center">
                                        <h2 class="text-primary">${calc.trips_count}</h2>
                                        <p>Total Trips</p>
                                        <small class="text-muted">In period</small>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>

                    <!-- Premium Breakdown -->
                    <div class="col-md-12">
                        <div class="kt-portlet">
                            <div class="kt-portlet__head">
                                <div class="kt-portlet__head-label">
                                    <h3 class="kt-portlet__head-title"><i class="flaticon-calculator"></i> Premium Breakdown</h3>
                                </div>
                            </div>
                            <div class="kt-portlet__body">
                                <div class="row">
                                    <div class="col-md-6">
                                        <table class="table table-bordered">
                                            <tr>
                                                <td class="font-weight-bold" width="50%">Monthly Premium:</td>
                                                <td>P ${calc.monthly_premium.toFixed(2)}</td>
                                            </tr>
                                            <tr>
                                                <td class="font-weight-bold">Base Rate per KM:</td>
                                                <td>P ${calc.base_rate_per_km.toFixed(4)}</td>
                                            </tr>
                                            <tr>
                                                <td class="font-weight-bold">Final Rate per KM:</td>
                                                <td>P ${calc.final_rate_per_km.toFixed(4)}</td>
                                            </tr>
                                            <tr>
                                                <td class="font-weight-bold">Actual Distance:</td>
                                                <td>${calc.actual_distance_km} km</td>
                                            </tr>
                                            <tr>
                                                <td class="font-weight-bold">Billable Distance:</td>
                                                <td>
                                                    ${calc.billable_distance_km} km
                                                    ${calc.actual_distance_km !== calc.billable_distance_km 
                                                        ? `<span class="text-warning ml-2"><small>(Adjusted)</small></span>` 
                                                        : ''}
                                                </td>
                                            </tr>
                                        </table>
                                    </div>
                                    <div class="col-md-6">
                                        <table class="table table-bordered">
                                            <tr>
                                                <td class="font-weight-bold" width="50%">Base Premium:</td>
                                                <td>P ${calc.base_premium.toFixed(2)}</td>
                                            </tr>
                                            <tr>
                                                <td class="font-weight-bold">Surcharge Amount:</td>
                                                <td>
                                                    P ${calc.surcharge_amount.toFixed(2)}
                                                    <small class="text-muted">(${calc.behaviour_surcharge_percentage}%)</small>
                                                </td>
                                            </tr>
                                            <tr class="kt-bg-success">
                                                <td class="font-weight-bold text-white">Total Premium:</td>
                                                <td class="font-weight-bold text-white">P ${calc.total_premium.toFixed(2)}</td>
                                            </tr>
                                            <tr>
                                                <td class="font-weight-bold">Premium Source:</td>
                                                <td>
                                                    <span class="kt-badge kt-badge-${calc.premium_source === 'Policy Table' ? 'success' : 'info'} kt-badge--inline">
                                                        ${calc.premium_source}
                                                    </span>
                                                </td>
                                            </tr>
                                            <tr>
                                                <td class="font-weight-bold">Calculation Date:</td>
                                                <td>${calc.created_at || new Date().toLocaleString()}</td>
                                            </tr>
                                        </table>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>

                    <!-- Calculation Steps -->
                    <div class="col-md-12">
                        <div class="kt-portlet">
                            <div class="kt-portlet__head">
                                <div class="kt-portlet__head-label">
                                    <h3 class="kt-portlet__head-title"><i class="flaticon-list"></i> Calculation Steps</h3>
                                </div>
                            </div>
                            <div class="kt-portlet__body">
                                <ol>
                                    ${Object.values(calc.calculation_breakdown).map(step => `<li>${step}</li>`).join('')}
                                </ol>
                            </div>
                        </div>
                    </div>
                </div>
            `;

            $('#premiumDetailsContent').html(detailsHTML);
            $('#premiumDetailsModal').modal('show');
        };
    });

</script>

</body>
<!-- end::Body -->

</html>


